## [:check_threshold]
## check a value against a configurable threshold
##
## Usage:
##   $code{'check_threshold'}->( { value => 42 } );
## Returns: { mode => TRUE, data => 1 } if under threshold
##          { mode => FALSE, data => "exceeded" } if over

use perlmod.load;

my $config = <[some.config.key]>;
my $threshold = 30;

if ( exists $config->{threshold} ) {
    $threshold = $config->{threshold};
}

my $value = shift @ARG;
$value = 0 if !defined $value;

if ( $value > $threshold ) {
    my $msg = sprintf(
        "value %d exceeds threshold %d",
        $value,
        $threshold,
    );

    <[base.logs]>()->( 1, $msg );

    return { mode => FALSE, data => "exceeded" };
}

return { mode => TRUE, data => 1 };
